// Ключевые фразы из путеводителей (Guidebook) всех пройденных разделов Duolingo.
// unit — номер раздела в пути курса, cefr — уровень, title — тема раздела,
// phrases — [английский, русский]. Пополняется после каждого пройденного раздела.
const KEY_PHRASES = [{"unit": 0, "cefr": "Intro", "title": "Предложи или прими напиток", "phrases": [["Tea, please.", "Чай, пожалуйста."], ["Coffee or tea?", "Кофе или чай?"], ["Welcome!", "Добро пожаловать!"], ["Thank you, goodbye!", "Спасибо, до свидания!"], ["Water, please.", "Воды, пожалуйста."]]}, {"unit": 1, "cefr": "Intro", "title": "Обсуди страны происхождения", "phrases": [["I am from Japan.", "Я из Японии."], ["I am from Paris, and you?", "Я из Парижа, а ты?"], ["China and Mexico", "Китай и Мексика"], ["I am from Brazil.", "Я из Бразилии."], ["I am from France too.", "Я тоже из Франции."]]}, {"unit": 2, "cefr": "Intro", "title": "Представь членов семьи", "phrases": [["This is my dad.", "Это мой папа."], ["Hi, my name is Anna!", "Привет, меня зовут Анна!"], ["My mom is from France.", "Моя мама из Франции."], ["Anna and Max", "Анна и Макс"], ["This is David.", "Это Дэвид."]]}, {"unit": 3, "cefr": "Intro", "title": "Найди путь в терминале аэропорта", "phrases": [["Welcome to Paris!", "Добро пожаловать в Париж!"], ["Is this my ticket?", "Это мой билет?"], ["Your ticket, please.", "Ваш билет, пожалуйста."], ["Yes, this is my phone.", "Да, это мой телефон."], ["Is this your bag?", "Это ваша сумка?"]]}, {"unit": 4, "cefr": "Intro", "title": "Покажи город гостям", "phrases": [["Welcome to my city!", "Добро пожаловать в мой город!"], ["This museum is famous.", "Этот музей знаменит."], ["Your house is big, right?", "Твой дом большой, да?"], ["This park is very nice.", "Этот парк очень приятный."], ["Tokyo is big.", "Токио большой город."]]}, {"unit": 5, "cefr": "Intro", "title": "Заказывай обед в ресторане", "phrases": [["Excuse me, I'd like a glass of water.", "Извините, я хотел бы стакан воды."], ["I'd like a sandwich, please.", "Я хотел бы бутерброд, пожалуйста."], ["Where is my salad?", "Где мой салат?"], ["This restaurant is very expensive!", "Этот ресторан очень дорогой!"], ["Here is your pizza.", "Вот ваша пицца."]]}, {"unit": 6, "cefr": "Intro", "title": "Обсуди разные профессии", "phrases": [["I'm a doctor.", "Я врач."], ["My wife is a lawyer.", "Моя жена юрист."], ["Is Lisa a doctor?", "Лиза врач?"], ["David is my nurse.", "Дэвид мой медбрат."], ["My mom is a doctor too.", "Моя мама тоже врач."]]}, {"unit": 7, "cefr": "Intro", "title": "Обсуди изучаемые и изученные языки", "phrases": [["I speak Hindi at home.", "Я говорю на хинди дома."], ["Yes, I study English at school.", "Да, я изучаю английский в школе."], ["You speak English and Hindi, right?", "Вы говорите на английском и на хинди, правда?"], ["I speak Spanish and English.", "Я говорю по-испански и по-английски."], ["I understand a little Hindi.", "Я немного понимаю хинди."]]}, {"unit": 8, "cefr": "Intro", "title": "Обсуди погоду", "phrases": [["It's cold today!", "Сегодня холодно!"], ["Is it rainy in your city?", "В твоём городе дождливо?"], ["You need a jacket today.", "Тебе нужна куртка сегодня."], ["It's sunny in Paris today.", "Сегодня в Париже солнечно."], ["I need a hat and a scarf.", "Мне нужны шляпа и шарф."]]}, {"unit": 9, "cefr": "Intro", "title": "Расскажи о своих питомцах", "phrases": [["Yes, I have a dog.", "Да, у меня есть собака."], ["My cat is very smart.", "Моя кошка очень умная."], ["Your pets are very cute.", "Твои питомцы очень милые."], ["Don't worry, my pets are quiet.", "Не беспокойся, мои питомцы тихие."], ["I have a dog and three cats.", "У меня есть собака и три кошки."]]}, {"unit": 10, "cefr": "A1", "title": "Покупай продукты", "phrases": [["Is that red skirt on sale?", "Та красная юбка на распродаже?"], ["This sweater is cheap!", "Этот свитер дешёвый!"], ["I want a new jacket.", "Я хочу новую куртку."], ["Excuse me, how much is this hat?", "Извините, сколько стоит эта шляпа?"], ["Oh, this store is expensive!", "Ой, этот магазин дорогой!"]]}, {"unit": 11, "cefr": "A1", "title": "Опиши планировку своего дома", "phrases": [["Welcome to my new apartment!", "Добро пожаловать в мою новую квартиру!"], ["The kitchen is big and beautiful.", "Кухня большая и красивая."], ["Have a seat on the couch.", "Присаживайтесь на диван."], ["Your apartment is clean!", "Твоя квартира чистая!"], ["Hi, come in!", "Привет, заходи!"]]}, {"unit": 12, "cefr": "A1", "title": "Представляйся на вечеринках", "phrases": [["Hi, I am Lisa.", "Привет, я Лиза."], ["This is a fun party.", "Это весёлая вечеринка."], ["Where is my friend Sara?", "Где моя подруга Сара?"], ["Yes, we are classmates.", "Да, мы одноклассники."], ["Nice to meet you, Max!", "Приятно познакомиться, Макс!"]]}, {"unit": 13, "cefr": "A1", "title": "Представь семью друзьям", "phrases": [["Hi, I'm David.", "Привет, я Дэвид."], ["Maria is smart and friendly.", "Мария умная и дружелюбная."], ["Oh, you're from Tokyo too!", "О, ты тоже из Токио!"], ["He's my cousin.", "Он мой двоюродный брат."], ["Don't worry, he is friendly.", "Не волнуйся, он дружелюбный."]]}, {"unit": 14, "cefr": "A1", "title": "Закажи завтрак в кафе", "phrases": [["I'd like a table for two.", "Я бы хотел столик на двоих."], ["Is the vegetarian burger spicy?", "Вегетарианский бургер острый?"], ["How much is a coffee?", "Сколько стоит кофе?"], ["This drink is delicious.", "Этот напиток вкусный."], ["Are your desserts very sweet?", "Ваши десерты очень сладкие?"]]}, {"unit": 15, "cefr": "A1", "title": "Знакомься с новыми с коллегами", "phrases": [["I need a new job.", "Мне нужна новая работа."], ["Is Ms. Jones at work today?", "Госпожа Джонс на работе сегодня?"], ["Excuse me, are these your keys?", "Извините, это ваши ключи?"], ["My new job is very interesting.", "Моя новая работа очень интересная."], ["This is your new office, Mr. Jones.", "Это ваш новый кабинет, мистер Джонс."]]}, {"unit": 16, "cefr": "A1", "title": "Обсуди чувства и новости", "phrases": [["I'm happy, and I'm excited!", "Я счастлив и в восторге!"], ["How is your mom?", "Как твоя мама?"], ["No, my family is not surprised.", "Нет, моя семья не удивлена."], ["Are you tired, Max?", "Ты устал, Макс?"], ["My daughter is sad.", "Моя дочь грустит."]]}, {"unit": 17, "cefr": "A1", "title": "Задавай вопросы в классе", "phrases": [["Is this a test?", "Это тест?"], ["I'm confused, is this the right book?", "Я запутался, это правильная книга?"], ["This is not the right answer.", "Это неправильный ответ."], ["Do you need help?", "Вам нужна помощь?"], ["Where is my classroom?", "Где мой кабинет?"]]}, {"unit": 18, "cefr": "A1", "title": "Делай покупки в торговом центре", "phrases": [["How much is this doll?", "Сколько стоит эта кукла?"], ["Where are the laptops?", "Где ноутбуки?"], ["The mall is near my house.", "Торговый центр рядом с моим домом."], ["I need two dolls!", "Мне нужны две куклы!"], ["Is the shoe store open?", "Обувной магазин открыт?"]]}, {"unit": 19, "cefr": "A1", "title": "Пользуйся общественным транспортом", "phrases": [["Where is the nearest train station?", "Где ближайшая железнодорожная станция?"], ["Excuse me, where is the bus station?", "Извините, где автовокзал?"], ["It's three o'clock, and I need coffee.", "Сейчас три часа, и мне нужен кофе."], ["Is this taxi available?", "Это такси свободно?"], ["My bus is here, see you later!", "Мой автобус здесь, увидимся позже!"]]}, {"unit": 20, "cefr": "A1", "title": "Обсуди предпочтения в спорте", "phrases": [["I love coffee, soccer, and cats!", "Я люблю кофе, футбол и кошек!"], ["Who is your favorite player?", "Кто твой любимый игрок?"], ["We both like tennis.", "Мы оба любим теннис."], ["My favorite sport is baseball.", "Мой любимый спорт — бейсбол."], ["You both love soccer!", "Вы оба любите футбол!"]]}, {"unit": 21, "cefr": "A1", "title": "Обсуди обязанности по дому", "phrases": [["We clean every Saturday.", "Мы убираемся каждую субботу."], ["He cooks every day.", "Он готовит каждый день."], ["I sweep the floor every week.", "Я подметаю пол каждую неделю."], ["Tom washes the windows every month.", "Том моет окна каждый месяц."], ["We watch TV at night.", "Мы смотрим телевизор ночью."]]}, {"unit": 22, "cefr": "A1", "title": "Опиши повседневные дела", "phrases": [["On Thursdays, I go to the gym.", "По четвергам я хожу в спортзал."], ["Are you busy on Mondays?", "Вы заняты по понедельникам?"], ["We often eat dinner in a restaurant.", "Мы часто ужинаем в ресторане."], ["I sometimes go to the mall.", "Я иногда хожу в торговый центр."], ["My manager is busy on Tuesdays.", "Мой менеджер занят по вторникам."]]}, {"unit": 23, "cefr": "A1", "title": "Забронируй номер в отеле", "phrases": [["I need a reservation, please.", "Мне нужна бронь, пожалуйста."], ["Are you on vacation?", "Вы в отпуске?"], ["Yes, we have rooms available.", "Да, у нас есть свободные номера."], ["How much is a room?", "Сколько стоит номер?"], ["Pets are not allowed at this hotel.", "В этом отеле домашние животные не разрешены."]]}, {"unit": 24, "cefr": "A1", "title": "Покупай продукты для ужина", "phrases": [["We need an onion and a tomato.", "Нам нужны луковица и помидор."], ["I'd like a bottle of cold water.", "Я бы хотел бутылку холодной воды."], ["My mom loves ice cream.", "Моя мама любит мороженое."], ["Do you need a bottle of water?", "Вам нужна бутылка воды?"], ["This banana is very sweet.", "Этот банан очень сладкий."]]}, {"unit": 25, "cefr": "A1", "title": "Опиши членов семьи", "phrases": [["My grandparents have an old car.", "У моих бабушки и дедушки есть старая машина."], ["Your uncle speaks English, right?", "Твой дядя говорит по-английски, да?"], ["I have blue eyes.", "У меня голубые глаза."], ["They love their children.", "Они любят своих детей."], ["My aunt is a lawyer.", "Моя тётя юрист."]]}, {"unit": 26, "cefr": "A1", "title": "Опиши личные вещи", "phrases": [["My room is near the bathroom.", "Моя комната рядом с ванной."], ["Those books are for our class.", "Те книги для нашего класса."], ["I really need a new desk.", "Мне очень нужен новый письменный стол."], ["This is a picture of my dad.", "Это фотография моего папы."], ["You have a piano in your room!", "У тебя в комнате есть пианино!"]]}, {"unit": 27, "cefr": "A1", "title": "Найди забытые вещи", "phrases": [["Oh no, my jacket is not here!", "О нет, моей куртки здесь нет!"], ["Is that your hat?", "Это твоя шляпа?"], ["What kind of dog do you have?", "Какая у тебя собака?"], ["Are these your glasses?", "Это ваши очки?"], ["My phone is lost.", "Мой телефон пропал."]]}, {"unit": 28, "cefr": "A1", "title": "Покупай одежду", "phrases": [["This dress is nice, and it's cheap.", "Это платье симпатичное, и оно дешёвое."], ["I need a new dress.", "Мне нужно новое платье."], ["Those boots are nice, and they are cheap.", "Те сапоги хорошие, и они дешёвые."], ["I want red boots!", "Я хочу красные сапоги!"], ["This store has so many shoes.", "В этом магазине так много обуви."]]}, {"unit": 29, "cefr": "A1", "title": "Опиши еду на рынке", "phrases": [["Good afternoon, how much is this cake?", "Добрый день, сколько стоит этот торт?"], ["These cherries are really sweet!", "Эти черешни очень сладкие!"], ["Do you need a bag?", "Вам нужен мешок?"], ["I need a pound of tomatoes.", "Мне нужен фунт помидоров."], ["A lot of families go shopping here.", "Много семей ходят за покупками здесь."]]}, {"unit": 30, "cefr": "A1", "title": "Спроси дорогу", "phrases": [["Excuse me, are you lost?", "Извините, вы заблудились?"], ["I do not have a map.", "У меня нет карты."], ["Where is the pharmacy?", "Где аптека?"], ["We are not tourists!", "Мы не туристы!"], ["Oh no, I'm very lost.", "О нет, я совсем заблудился."]]}, {"unit": 31, "cefr": "A1", "title": "Обсуди игры на выходные", "phrases": [["I usually enjoy soccer.", "Мне обычно нравится футбол."], ["Julia always wins our card games.", "Юлия всегда выигрывает в наших карточных играх."], ["We sometimes play card games at night.", "Мы иногда играем в карточные игры ночью."], ["He doesn't understand the game.", "Он не понимает игры."], ["Volleyball is my favorite sport.", "Волейбол — мой любимый спорт."]]}, {"unit": 32, "cefr": "A1", "title": "Посети врача", "phrases": [["I have a bad cold.", "У меня сильная простуда."], ["Do you need a doctor?", "Вам нужен врач?"], ["My stomach hurts.", "У меня болит живот."], ["He has the flu.", "У него грипп."], ["I feel better today.", "Я чувствую себя лучше сегодня."]]}, {"unit": 33, "cefr": "A1", "title": "Узнай о магазине", "phrases": [["Excuse me, where do I pay?", "Извините, где заплатить?"], ["What size do you need?", "Какой вам нужен размер?"], ["I always pay with a card.", "Я всегда плачу картой."], ["Do you want a plastic bag?", "Хотите пластиковый пакет?"], ["How much does this cost?", "Сколько это стоит?"]]}, {"unit": 34, "cefr": "A1", "title": "Опиши семейные занятия в выходные", "phrases": [["We play video games every weekend.", "Мы играем в компьютерные игры каждые выходные."], ["Dad is cooking pizza for our snack.", "Папа готовит пиццу для нашего перекуса."], ["Anna is running in the park.", "Анна бежит в парке."], ["Do you want toast for breakfast?", "Хочешь тост на завтрак?"], ["Mom is writing her book right now.", "Мама пишет свою книгу прямо сейчас."]]}, {"unit": 35, "cefr": "A1", "title": "Строй планы в соответствии с погодой", "phrases": [["How is the weather today?", "Как погода сегодня?"], ["Wow, those mountains are beautiful.", "Ух ты, те горы красивые."], ["I'm taking a picture.", "Я фотографирую."], ["It's sunny and we're relaxing outside.", "Солнечно, и мы отдыхаем на улице."], ["A bear is walking near our tent!", "Медведь идет рядом с нашей палаткой!"]]}, {"unit": 36, "cefr": "A1", "title": "Обсуди задачи группового проекта", "phrases": [["What are you doing right now?", "Что ты делаешь прямо сейчас?"], ["We discuss the project every day.", "Мы обсуждаем проект каждый день."], ["Are you studying a new language?", "Вы изучаете новый язык?"], ["I am writing a book!", "Я пишу книгу!"], ["The coffee shop is near the library.", "Кофейня рядом с библиотекой."]]}, {"unit": 37, "cefr": "A1", "title": "Обсуди школьные предметы и учителей", "phrases": [["What is your favorite subject?", "Какой твой любимый предмет?"], ["I'm excited about our science project.", "Я в восторге от нашего научного проекта."], ["Do you like math?", "Ты любишь математику?"], ["We study math on Tuesdays and Fridays.", "Мы занимаемся математикой по вторникам и пятницам."], ["My favorite subject is science.", "Мой любимый предмет — естествознание."]]}, {"unit": 38, "cefr": "A1", "title": "Стройте планы с друзьями", "phrases": [["Let's have coffee today.", "Давай выпьем кофе сегодня."], ["Are you free right now?", "Вы сейчас свободны?"], ["Please call me after school.", "Пожалуйста, позвони мне после школы."], ["Join us on Saturday!", "Присоединяйтесь к нам в субботу!"], ["OK, let's meet at the park.", "Хорошо, давай встретимся в парке."]]}, {"unit": 39, "cefr": "A1", "title": "Обсуди советы по безопасности в городе", "phrases": [["Be careful, the street is busy!", "Осторожно, улица оживлена!"], ["Is this area safe?", "Этот район безопасен?"], ["Don't go swimming alone.", "Не купайтесь в одиночку."], ["Please bring a bottle of water.", "Пожалуйста, принесите бутылку воды."], ["Let's cross the street together.", "Давай перейдём улицу вместе."]]}, {"unit": 40, "cefr": "A1", "title": "Обсуди фитнес-занятия", "phrases": [["I do yoga on Wednesdays.", "Я занимаюсь йогой по средам."], ["Can you do push-ups?", "Ты умеешь отжиматься?"], ["Eat healthy meals.", "Ешьте здоровую пищу."], ["Wow, can she do fifty push-ups?", "Ничего себе, она может сделать пятьдесят отжиманий?"], ["I can't lift heavy weights.", "Я не могу поднимать тяжести."]]}, {"unit": 41, "cefr": "A1", "title": "Давай инструкции по дому", "phrases": [["Can you park my car in the garage?", "Вы можете припарковать мою машину в гараже?"], ["Could you clean my fridge, please?", "Не могли бы вы почистить мой холодильник, пожалуйста?"], ["Please walk the dog.", "Пожалуйста, выведите собаку на прогулку."], ["Can you check the mail every day?", "Можешь проверять почту каждый день?"], ["Could you feed my dog in the evening?", "Вы могли бы покормить мою собаку вечером?"]]}, {"unit": 42, "cefr": "A1", "title": "Обсуди планы поездки", "phrases": [["We will travel to Japan next year.", "Мы поедем в Японию в следующем году."], ["How long will you stay in Australia?", "Как долго ты будешь в Австралии?"], ["They'll stay with friends in Australia.", "Они остановятся у друзей в Австралии."], ["Will you travel to Europe next week?", "Ты поедешь в Европу на следующей неделе?"], ["I'll take a flight to Africa.", "Я полечу в Африку."]]}, {"unit": 43, "cefr": "A1", "title": "Выбери развлечения в парке", "phrases": [["Let's go to a theme park!", "Пойдём в парк развлечений!"], ["Can you wait in line, please?", "Вы можете подождать в очереди, пожалуйста?"], ["Next time, let's bring sandwiches.", "В следующий раз давай возьмём с собой бутерброды."], ["I love roller coasters.", "Я люблю американские горки."], ["How about the theme park near Paris?", "Как насчёт парка развлечений недалеко от Парижа?"]]}, {"unit": 44, "cefr": "A1", "title": "Покупай средства гигиены", "phrases": [["Do you sell bandages?", "Вы продаёте бинты?"], ["I need pills for the flu.", "Мне нужны таблетки от гриппа."], ["My throat really hurts!", "Горло очень болит!"], ["This medicine is expensive, but I have a coupon!", "Это лекарство дорогое, но у меня есть купон!"], ["Do you need paper towels, or do you need soap?", "Вам нужны бумажные полотенца или вам нужно мыло?"]]}, {"unit": 45, "cefr": "A1", "title": "Обсуди предпочтения на Супербоул", "phrases": [["I'm excited about the big game!", "Я в предвкушении большого матча!"], ["I like watching the Super Bowl!", "Я люблю смотреть Супербоул!"], ["We love drinking beer during the Super Bowl.", "Мы любим пить пиво во время Супербоула."], ["My grandma likes watching football.", "Моя бабушка любит смотреть футбол."], ["The Super Bowl is a big game.", "Супербоул — большой матч."]]}, {"unit": 46, "cefr": "A1", "title": "Общайся с коллегами эффективно", "phrases": [["Can you hear me?", "Меня слышно?"], ["I'll ask our lawyers.", "Я спрошу наших юристов."], ["We can't quite hear you.", "Тебя плохо слышно."], ["Let's discuss it tomorrow.", "Давайте обсудим это завтра."], ["You're on mute.", "У тебя выключен микрофон."]]}, {"unit": 47, "cefr": "A1", "title": "Сделай заказ по меню", "phrases": [["I'd like a glass of wine, please.", "Я бы хотел бокал вина, пожалуйста."], ["Can we order more bread?", "Можно заказать ещё хлеба?"], ["The bill is ninety dollars.", "Счёт составляет девяносто долларов."], ["Save some dessert for me, please!", "Прибереги немного десерта для меня, пожалуйста!"], ["I'll sit by you.", "Я сяду рядом с тобой."]]}, {"unit": 48, "cefr": "A1", "title": "Спланируй вечер в городе", "phrases": [["Let's order some drinks.", "Давайте закажем напитки."], ["Look, there is a concert at that bar!", "Смотри, в том баре концерт!"], ["There are delicious drinks.", "Есть вкусные напитки."], ["Is there a bar near here?", "Есть ли здесь поблизости бар?"], ["We both really like dancing!", "Мы оба очень любим танцевать!"]]}, {"unit": 49, "cefr": "A1", "title": "Управляйся с общественным транспортом", "phrases": [["Our trip ends tomorrow.", "Наша поездка заканчивается завтра."], ["When does the next train leave?", "Когда отправляется следующий поезд?"], ["Tonight, the subway closes at twelve.", "Сегодня ночью метро закроется в двенадцать."], ["Can we walk to the station?", "Мы можем дойти до станции пешком?"], ["The bus gets here in half an hour.", "Автобус приедет сюда через полчаса."]]}, {"unit": 50, "cefr": "A1", "title": "Эффективно работай из дома", "phrases": [["My inbox is full.", "Мои входящие полны."], ["Could you send an email to the boss?", "Вы могли бы отправить электронное письмо начальнику?"], ["The meeting is online.", "Встреча онлайн."], ["I don't remember my Wi-Fi password!", "Я не помню свой пароль от Wi-Fi!"], ["Please type your first name.", "Пожалуйста, введите ваше имя."]]}, {"unit": 51, "cefr": "A1", "title": "Отвечай на вопросы на собеседовании", "phrases": [["Tell me about your last job.", "Расскажите мне о своей последней работе."], ["I was a manager there.", "Я был там менеджером."], ["What were your responsibilities?", "Какие у вас были обязанности?"], ["Are you interested in this position?", "Вы интересуетесь этой должностью?"], ["My last boss is still a friend.", "Мой предыдущий начальник всё ещё мой друг."]]}, {"unit": 52, "cefr": "A1", "title": "Опиши плохой день", "phrases": [["The cat was behind the door!", "Кошка была за дверью!"], ["Why was the closet empty?", "Почему шкаф был пуст?"], ["The dining room was clean.", "Столовая была чистой."], ["The fridge was empty!", "Холодильник был пуст!"], ["The kids were in the kitchen.", "Дети были на кухне."]]}, {"unit": 53, "cefr": "A1", "title": "Обсуди опыт учёбы в колледже", "phrases": [["Where do you go to college?", "В каком колледже ты учишься?"], ["My major is business.", "Моя специальность – бизнес."], ["Listen to the professor and take notes.", "Слушайте профессора и делайте заметки."], ["I have a class in Canada this summer.", "У меня будет курс в Канаде этим летом."], ["The homework is on the board.", "Домашнее задание на доске."]]}, {"unit": 54, "cefr": "A1", "title": "Возвращай бракованный товар", "phrases": [["Excuse me, I have a problem.", "Извините, у меня проблема."], ["Can I return this item?", "Могу ли я вернуть этот товар?"], ["How can I get a refund?", "Как мне вернуть деньги?"], ["My laptop has a problem.", "У моего ноутбука проблема."], ["Where is customer service?", "Где отдел обслуживания клиентов?"]]}, {"unit": 55, "cefr": "A1", "title": "Покупай продукты", "phrases": [["Do we have enough apples?", "У нас достаточно яблок?"], ["Let's buy mushrooms for the pizza.", "Давай купим грибы на пиццу."], ["Can you put this pie in our cart?", "Можешь положить этот пирог в нашу тележку?"], ["I don't see any milk in the fridge.", "Я не вижу молока в холодильнике."], ["What aisle is the oil on?", "В каком ряду масло?"]]}, {"unit": 56, "cefr": "A1", "title": "Делай запросы в отеле", "phrases": [["Good evening, can I help you?", "Добрый вечер, могу ли я вам помочь?"], ["Will you fix the heat, please?", "Вы почините отопление, пожалуйста?"], ["Can we check out at four o'clock?", "Мы можем выехать в четыре часа?"], ["Please check in at the front desk.", "Пожалуйста, зарегистрируйтесь на стойке регистрации."], ["Thank you for carrying my suitcase.", "Спасибо, что несёте мой чемодан."]]}, {"unit": 57, "cefr": "A1", "title": "Отправляй посылки и письма", "phrases": [["I would like to buy two envelopes.", "Я бы хотел купить два конверта."], ["How can I help you today?", "Чем я могу вам помочь сегодня?"], ["Would you like to send this today?", "Вы бы хотели отправить это сегодня?"], ["This is a letter for my grandpa.", "Это письмо для моего дедушки."], ["I would like to send a card.", "Я хотел бы отправить открытку."]]}, {"unit": 58, "cefr": "A1", "title": "Обсуди домашние дела", "phrases": [["I have two daily chores.", "У меня два ежедневных дела по дому."], ["Could you do the dishes, please?", "Не могли бы вы помыть посуду, пожалуйста?"], ["The apartment is a mess!", "В квартире беспорядок!"], ["Do you have any dirty laundry?", "У тебя есть грязное бельё?"], ["Let's vacuum the house.", "Давай пропылесосим дом."]]}, {"unit": 59, "cefr": "A1", "title": "Обсуди чувства в отношениях", "phrases": [["I'm worried about you.", "Я переживаю за тебя."], ["Why do you feel upset?", "Почему ты расстроен?"], ["I sometimes feel really lonely.", "Я иногда чувствую себя очень одиноко."], ["Don't worry, I'm not mad at you.", "Не волнуйся, я не злюсь на тебя."], ["Can you explain that?", "Можешь объяснить это?"]]}, {"unit": 60, "cefr": "A1", "title": "Обсуди планы на отпуск", "phrases": [["I am going to visit Egypt in October.", "Я собираюсь посетить Египет в октябре."], ["Can we take a bus there?", "Мы можем доехать туда на автобусе?"], ["You'll need your passport in Egypt.", "В Египте тебе понадобится паспорт."], ["We are going to travel across the ocean.", "Мы собираемся пересечь океан."], ["I am going to pack next week!", "Я собираюсь упаковать вещи на следующей неделе!"]]}, {"unit": 61, "cefr": "A1", "title": "Договаривайся с друзьями", "phrases": [["Are you going to see your friends later?", "Ты собираешься встретиться со своими друзьями позже?"], ["Let's bring some food and have a picnic!", "Давайте возьмём немного еды и устроим пикник!"], ["I plan to study tomorrow night.", "Я планирую заниматься завтра вечером."], ["Are you going to call me this afternoon?", "Ты собираешься позвонить мне сегодня днём?"], ["The wedding is going to be fancy.", "Свадьба будет шикарной."]]}, {"unit": 62, "cefr": "A1", "title": "Обсуди погоду в прошлые выходные", "phrases": [["Is winter your favorite season?", "Зима твоя любимая пора года?"], ["It snowed a lot last February.", "В прошлом феврале выпало много снега."], ["It's always cold in December.", "Всегда холодно в декабре."], ["It was too humid last weekend!", "Было слишком влажно в прошлые выходные!"], ["Spring is my favorite season.", "Весна — моё любимое время года."]]}, {"unit": 63, "cefr": "A1", "title": "Обсуди болезнь", "phrases": [["My cough started yesterday.", "Вчера у меня начался кашель."], ["Please see a doctor, Kevin!", "Пожалуйста, сходи к врачу, Кевин!"], ["I stayed in bed because I was sick.", "Я лежал в постели, потому что я болел."], ["How's your health today?", "Как ваше здоровье сегодня?"], ["You need to get some rest.", "Тебе нужно отдохнуть."]]}, {"unit": 64, "cefr": "A1", "title": "Поделись детскими воспоминаниями", "phrases": [["Did you play video games after school?", "Вы играли в видеоигры после школы?"], ["I loved cherry jam.", "Я любил вишнёвое варенье."], ["My brother was a rugby player.", "Мой брат был регбистом."], ["We usually played baseball after school.", "Мы обычно играли в бейсбол после школы."], ["I cried on my first day of school.", "Я плакал в первый день школы."]]}, {"unit": 65, "cefr": "A1", "title": "Ориентируйся в ЧС", "phrases": [["Who was in the waiting room with you?", "Кто был с тобой в зале ожидания?"], ["My scooter is broken!", "Мой скутер сломан!"], ["Did you call an ambulance quickly?", "Вы быстро вызвали скорую помощь?"], ["I have a few bruises, but I'm fine!", "У меня несколько синяков, но я в порядке!"], ["The ambulance arrived very quickly.", "Скорая приехала очень быстро."]]}, {"unit": 66, "cefr": "A1", "title": "Принимай решения на фестивале", "phrases": [["This pop concert is fun!", "Этот поп-концерт классный!"], ["Who is your favorite rock band?", "Какая у тебя любимая рок-группа?"], ["Let's find seats near the stage.", "Давайте найдём места у сцены."], ["The last group performs at ten.", "Последняя группа выступает в десять."], ["Do you prefer rap or rock?", "Ты предпочитаешь рэп или рок?"]]}, {"unit": 67, "cefr": "A1", "title": "Обсуди жизнь знаменитостей", "phrases": [["This author is younger than my brother!", "Этот автор младше моего брата!"], ["She's very rich, and she owns an island!", "Она очень богата, и она владеет островом!"], ["That director's movies are the funniest!", "Фильмы того режиссёра самые смешные!"], ["Which band member is the rudest?", "Какой участник группы самый грубый?"], ["I love watching music videos.", "Я люблю смотреть музыкальные клипы."]]}, {"unit": 68, "cefr": "A1", "title": "Спланируй рабочий проект", "phrases": [["When is the deadline for the project?", "Когда крайний срок по проекту?"], ["Let's meet between one and two.", "Давай встретимся между часом и двумя часами."], ["Oops, did I make a mistake?", "Ой, я ошибся?"], ["The report is due tomorrow.", "Отчет нужно сдать завтра."], ["Can you explain the plans again?", "Вы можете ещё раз объяснить планы?"]]}, {"unit": 69, "cefr": "A1", "title": "Опиши случай ограбления", "phrases": [["Did you see anyone?", "Вы видели кого-нибудь?"], ["The detective wants to talk to you.", "Детектив хочет поговорить с вами."], ["My diamond earrings are missing!", "Мои бриллиантовые серьги пропали!"], ["Can you describe him?", "Можете описать его?"], ["Did you contact the detective?", "Вы связались с детективом?"]]}, {"unit": 70, "cefr": "A2", "title": "Поделись впечатлениями о праздниках", "phrases": [["The fireworks were beautiful.", "Фейерверки были красивыми."], ["We ate traditional food.", "Мы ели традиционную еду."], ["Did you enjoy the holidays?", "Тебе понравились праздники?"], ["I saw my grandparents last month.", "Я видел своих бабушку и дедушку в прошлом месяце."], ["On New Year's Eve, we watched fireworks.", "В новогоднюю ночь мы смотрели салют."]]}, {"unit": 71, "cefr": "A2", "title": "Запишись к врачу", "phrases": [["I'd like to make an appointment, please.", "Мне бы хотелось записаться на приём, пожалуйста."], ["Could you repeat your name, please?", "Могли бы вы повторить ваше имя, пожалуйста?"], ["Please confirm the appointment.", "Пожалуйста, подтвердите запись."], ["I need to see a dentist.", "Мне надо к стоматологу."], ["You can also make an appointment online.", "Вы также можете записаться на прием онлайн."]]}, {"unit": 72, "cefr": "A2", "title": "Обсуди снятие стресса", "phrases": [["How's it going, Emma?", "Как дела, Эмма?"], ["If I'm stressed out, I cook soup.", "Когда я в стрессе, я варю суп."], ["Do you call your mom when you're lonely?", "Ты звонишь маме, когда тебе одиноко?"], ["Take a nap if you feel terrible.", "Вздремни, если чувствуешь себя ужасно."], ["When I'm worried about something, I run!", "Когда я волнуюсь о чём-то, я бегаю!"]]}, {"unit": 73, "cefr": "A2", "title": "Спланируй поездку с друзьями", "phrases": [["Let's take a tour!", "Давайте сходим на экскурсию!"], ["How much luggage are you bringing?", "Сколько багажа ты берёшь с собой?"], ["If it's foggy, we'll stay inside.", "Если туманно, мы останемся в помещении."], ["I will ask for directions if I am lost.", "Я спрошу дорогу, если потеряюсь."], ["When we arrive, we'll unpack.", "Когда мы приедем, мы распакуемся."]]}, {"unit": 74, "cefr": "A2", "title": "Попроси совет по спортзалу", "phrases": [["Let's join a gym!", "Давай запишемся в спортзал!"], ["I take fitness classes.", "Я хожу на занятия по фитнесу."], ["You should bring a water bottle to class.", "Тебе стоит принести бутылку с водой на занятие."], ["I couldn't finish one workout.", "Я не смог закончить одну тренировку."], ["Do you want to join a gym?", "Ты хочешь записаться в тренажёрный зал?"]]}, {"unit": 75, "cefr": "A2", "title": "Обсуди здоровье с врачом", "phrases": [["Do you have back pain?", "У вас болит спина?"], ["You must not skip meals.", "Тебе нельзя пропускать приёмы пищи."], ["Please thank the nurses.", "Пожалуйста, поблагодарите медсестёр."], ["I have a medical appointment.", "У меня запись к врачу."], ["You must take this medicine every day.", "Вы должны принимать это лекарство каждый день."]]}, {"unit": 76, "cefr": "A2", "title": "Решай вопросы на дне рождения", "phrases": [["Happy birthday, Anna!", "С днём рождения, Анна!"], ["Did you get an invitation?", "Тебе пришло приглашение?"], ["I brought chips!", "Я принёс чипсы!"], ["How many invitations did you send?", "Сколько приглашений вы отправили?"], ["We had a wonderful evening.", "У нас был замечательный вечер."]]}, {"unit": 77, "cefr": "A2", "title": "Тактично объясняй ошибки на работе", "phrases": [["You sent the file to the wrong person.", "Вы отправили файл не тому человеку."], ["Could you copy this report?", "Могли бы вы скопировать этот отчёт?"], ["I'll write the report right away.", "Я напишу отчёт сразу."], ["If you can, show your presentation to Amy.", "Если можешь, покажи свою презентацию Эми."], ["Please bring the correct document to me.", "Пожалуйста, принесите мне правильный документ."]]}, {"unit": 78, "cefr": "A2", "title": "Делай покупки на рынке", "phrases": [["This rug is colorful.", "Этот ковёр разноцветный."], ["Can I get a pound of mangos?", "Можно фунт манго?"], ["The plastic one is cheaper.", "Пластиковый дешевле."], ["I love the gold ones!", "Я люблю золотые!"], ["This market is the most famous.", "Этот рынок самый известный."]]}, {"unit": 79, "cefr": "A2", "title": "Обсуди текущие проекты на работе", "phrases": [["We're ready for the presentation.", "Мы готовы к презентации."], ["The customer asked for a refund.", "Клиент попросил вернуть деньги."], ["I had a nice conversation with her.", "У меня был приятный разговор с ней."], ["The project is better now.", "Проект теперь лучше."], ["Do you have any suggestions?", "У вас есть какие-нибудь предложения?"]]}, {"unit": 80, "cefr": "A2", "title": "Обсуди стратегии саморазвития", "phrases": [["Make a budget before you go to the store.", "Составь бюджет перед тем, как пойдёшь в магазин."], ["Do you meditate after you exercise?", "Ты медитируешь после тренировки?"], ["Save money before you buy a house.", "Копите деньги, прежде чем купить дом."], ["I want to improve my computer skills.", "Я хочу улучшить свои навыки работы с компьютером."], ["Relax before you go to sleep.", "Расслабься перед сном."]]}, {"unit": 81, "cefr": "A2", "title": "Объясни проблемы с техникой", "phrases": [["My laptop got a virus.", "Мой ноутбук подхватил вирус."], ["Can I connect this charger to your laptop?", "Можно подключить это зарядное устройство к твоему ноутбуку?"], ["What happened when you clicked on the link?", "Что произошло, когда вы кликнули по ссылке?"], ["I lost all my email addresses.", "Я потерял все свои адреса электронной почты."], ["The battery isn't charging.", "Аккумулятор не заряжается."]]}, {"unit": 82, "cefr": "A2", "title": "Сплетничай о личной жизни", "phrases": [["My sister hears all the best stories!", "Моя сестра слышит все лучшие истории!"], ["I think that he's single.", "Я думаю, что он холост."], ["Did they break up?", "Они расстались?"], ["They enjoyed a romantic evening together.", "Они наслаждались романтическим вечером вместе."], ["I hope that they are happy together.", "Я надеюсь, что они счастливы вместе."]]}, {"unit": 83, "cefr": "A2", "title": "Обсуди здоровый образ жизни", "phrases": [["Try to avoid fried food.", "Старайтесь избегать жареной еды."], ["I want to change my diet.", "Я хочу сменить свой рацион."], ["Who's planning the retreat next year?", "Кто планирует уединённое место в следующем году?"], ["Good luck, I'm sure you'll do well!", "Удачи, я уверен, у тебя всё получится!"], ["Cycling is fun!", "Кататься на велосипеде весело!"]]}, {"unit": 84, "cefr": "A2", "title": "Покупай продукты в магазине", "phrases": [["Do you have any paper plates?", "У вас есть бумажные тарелки?"], ["Let's make barbecue tonight.", "Давай устроим барбекю сегодня вечером."], ["How much are those grapes?", "Почём тот виноград?"], ["I need basil for the sauce.", "Мне нужен базилик для соуса."], ["Do they have any peaches?", "У них есть персики?"]]}, {"unit": 85, "cefr": "A2", "title": "Обсуди проблемы района", "phrases": [["I met the new neighbors.", "Я познакомился с новыми соседями."], ["The mayor will talk about crimes in the city.", "Мэр будет говорить о преступлениях в городе."], ["Can I borrow your truck?", "Могу я одолжить у тебя грузовик?"], ["Some of my neighbors are complaining.", "Некоторые из моих соседей жалуются."], ["Let's meet the new neighbors!", "Давайте познакомимся с новыми соседями!"]]}, {"unit": 86, "cefr": "A2", "title": "Обсуди замену ингредиентов", "phrases": [["The stove is broken!", "Плита сломана!"], ["Do we have a recipe for green curry?", "Есть ли у нас рецепт зелёного карри?"], ["There is no milk in the fridge.", "В холодильнике нет молока."], ["How does the stove work?", "Как работает плита?"], ["Did you forget the teaspoon of salt?", "Вы забыли чайную ложку соли?"]]}, {"unit": 87, "cefr": "A2", "title": "Опиши неудачу в магазине", "phrases": [["The bookstore was busy.", "В книжном магазине было многолюдно."], ["I'm surprised a toy costs fifty dollars!", "Я удивлён, что игрушка стоит пятьдесят долларов!"], ["There was an angry customer here last night.", "Здесь прошлой ночью был сердитый клиент."], ["There were no sizes for tall people!", "Не было размеров для высоких людей!"], ["I finally got a refund.", "Мне наконец вернули деньги."]]}, {"unit": 88, "cefr": "A2", "title": "Пригласи друзей на праздник", "phrases": [["Congratulations, you graduated from college!", "Поздравляю, вы окончили колледж!"], ["Will there be any games or other activities?", "Будут игры или другие мероприятия?"], ["We will celebrate in the backyard.", "Мы отпразднуем на заднем дворе."], ["Please RSVP if you can join us!", "Пожалуйста, подтвердите участие, если сможете присоединиться к нам!"], ["There will be a fancy ceremony.", "Будет пышная церемония."]]}, {"unit": 89, "cefr": "A2", "title": "Обсуди вещи с соседями", "phrases": [["Whose TV is that?", "Чей это телевизор?"], ["This alarm clock is mine.", "Этот будильник мой."], ["I found a knife under the fridge.", "Я нашёл нож под холодильником."], ["These books are mine.", "Эти книги мои."], ["Whose shoes are under the couch?", "Чья обувь под диваном?"]]}, {"unit": 90, "cefr": "A2", "title": "Сравнивай культурные различия", "phrases": [["What do you think of Italian cuisine?", "Что ты думаешь об итальянской кухне?"], ["The architecture there is beautiful.", "Архитектура там красивая."], ["I'm as adventurous as him.", "Я такой же любитель приключений, как он."], ["The population is as big as New York's.", "Население такое же большое, как у Нью-Йорка."], ["Their cuisine represents their culture.", "Их кухня отражает их культуру."]]}, {"unit": 91, "cefr": "A2", "title": "Выбери подарок на день рождения", "phrases": [["Look at this pretty card!", "Посмотри на эту красивую открытку!"], ["Either set will be a good gift.", "Любой из двух наборов будет хорошим подарком."], ["I don't care, so it's up to you.", "Мне всё равно, так что решай ты."], ["These art sets are more affordable.", "Эти художественные наборы доступнее."], ["Remember, the party's tonight!", "Помни, вечеринка сегодня вечером!"]]}, {"unit": 92, "cefr": "A2", "title": "Обсуди активный отдых на улице", "phrases": [["I love walking in nature.", "Я люблю гулять на природе."], ["Do you ever go snowboarding?", "Ты когда-нибудь катаешься на сноуборде?"], ["The sun is hot and bright.", "Солнце жаркое и яркое."], ["We hike in the forest.", "Мы ходим в походы по лесу."], ["You're a great swimmer!", "Ты отлично плаваешь!"]]}, {"unit": 93, "cefr": "A2", "title": "Предлагай улучшения для проектов", "phrases": [["Can I suggest something?", "Можно я кое-что предложу?"], ["Let's schedule a meeting.", "Давайте назначим встречу."], ["Do you mind suggesting other options?", "Вы не против предложить другие варианты?"], ["Meeting in the conference room is convenient.", "Встречаться в конференц-зале удобно."], ["Thanks, I'd love that!", "Спасибо, с удовольствием!"]]}, {"unit": 94, "cefr": "A2", "title": "Обсуди любимые жанры кино", "phrases": [["Do you like horror movies?", "Ты любишь фильмы ужасов?"], ["The movie will begin at nine fifteen.", "Фильм начнётся в девять пятнадцать."], ["Everyone loves comedy movies!", "Все любят комедийные фильмы!"], ["The ending was definitely a surprise!", "Концовка определённо была сюрпризом!"], ["I definitely prefer action movies!", "Я определённо предпочитаю боевики!"]]}, {"unit": 95, "cefr": "A2", "title": "Обсуди качества кандидатов", "phrases": [["Did you vote for anybody last year?", "Вы голосовали за кого-нибудь в прошлом году?"], ["She's a great candidate.", "Она отличный кандидат."], ["Do you agree or disagree?", "Вы согласны или не согласны?"], ["I like reading about politics.", "Мне нравится читать о политике."], ["The election is important.", "Эти выборы важны."]]}, {"unit": 96, "cefr": "A2", "title": "Расскажи свою историю жизни", "phrases": [["I have lived in this town since last year.", "Я живу в этом городе с прошлого года."], ["How long have you played the keyboard?", "Как долго ты играешь на клавишных?"], ["I joined a gym last year.", "Я записался в спортзал в прошлом году."], ["She has lived in this town since last year.", "Она живёт в этом городе с прошлого года."], ["Do you collect coins?", "Вы коллекционируете монеты?"]]}, {"unit": 97, "cefr": "A2", "title": "Расскажи историю семьи", "phrases": [["There are four people in my family.", "В моей семье четыре человека."], ["My dad has taught biology for twenty years.", "Мой папа преподаёт биологию уже двадцать лет."], ["My family has visited Paris four times.", "Моя семья была в Париже четыре раза."], ["They have lived there since eighteen ninety.", "Они живут там с 1890 года."], ["I have flown to France six times.", "Я летал во Францию шесть раз."]]}, {"unit": 98, "cefr": "A2", "title": "Обсуди прошлый опыт работы", "phrases": [["Why did you choose this occupation?", "Почему вы выбрали эту профессию?"], ["I need more work experience.", "Мне нужно больше опыта работы."], ["Have you completed the application?", "Вы заполнили заявление?"], ["I'm currently looking for a new position.", "Я сейчас ищу новую должность."], ["Tell us about your previous experience.", "Расскажите нам о своем предыдущем опыте."]]}, {"unit": 99, "cefr": "A2", "title": "Успешно проведи поиск в интернете", "phrases": [["How do you spell her name?", "Как пишется её имя?"], ["Look up the facts online.", "Найдите факты в интернете."], ["I spoke to the teacher about it.", "Я поговорил с учителем об этом."], ["Perhaps the deadline is wrong.", "Может быть, крайний срок неверный."], ["I'll follow up tomorrow and email her.", "Завтра свяжусь с ней и напишу ей на почту."]]}, {"unit": 100, "cefr": "A2", "title": "Обсуди занятия в центре", "phrases": [["What time does the day care open?", "Во сколько открывается детский сад?"], ["I like to do exercise at the rec center.", "Мне нравится тренироваться в спортивно-развлекательном центре."], ["Can we play ping pong here?", "Мы можем здесь поиграть в пинг-понг?"], ["The fee is really expensive!", "Плата очень дорогая!"], ["Let's join the photography club!", "Давай вступим в фотографический клуб!"]]}, {"unit": 101, "cefr": "A2", "title": "Расскажи о необычных поездках", "phrases": [["What was the castle like?", "Каким был замок?"], ["I've never been to that castle.", "Я никогда не был в том замке."], ["The clouds were amazing.", "Облака были потрясающими."], ["Have you ever been to a foreign country?", "Вы когда‑нибудь были в иностранной стране?"], ["It was a fun adventure!", "Это было весёлое приключение!"]]}, {"unit": 102, "cefr": "A2", "title": "Обсуди переезд в новую квартиру", "phrases": [["Let's open the curtains.", "Давай откроем шторы."], ["The elevator skips the seventh floor!", "Лифт пропускает седьмой этаж!"], ["I haven't bought new curtains yet.", "Я ещё не купил новые шторы."], ["This room is quite ugly!", "Эта комната довольно уродливая!"], ["Have you paid the trash bill yet?", "Вы уже оплатили счет за вывоз мусора?"]]}, {"unit": 103, "cefr": "A2", "title": "Попроси повышение на работе", "phrases": [["I haven't gotten a raise since they hired me!", "Мне не повышали зарплату с тех пор, как меня наняли!"], ["I'm a businesswoman, so I understand business!", "Я деловая женщина, поэтому я разбираюсь в бизнесе!"], ["I deserve more benefits, such as insurance.", "Я заслуживаю больше льгот, таких как страховка."], ["I've been a reliable employee since I began!", "Я надежный сотрудник с самого начала!"], ["I'd like to ask for a promotion.", "Я хотел бы попросить о повышении."]]}, {"unit": 104, "cefr": "A2", "title": "Ориентируйся в новом городе", "phrases": [["Go straight, and you will see the hotel.", "Идите прямо, и вы увидите отель."], ["Excuse me, young man, where's platform two?", "Извините, молодой человек, где вторая платформа?"], ["Turn left after you cross the bridge.", "Поверните налево после того, как пересечёте мост."], ["Can you write the directions down, please?", "Можете записать указания, пожалуйста?"], ["Let's ask the man at the gas station.", "Давай спросим у мужчины на заправке."]]}, {"unit": 105, "cefr": "A2", "title": "Покупай одежду для мероприятия", "phrases": [["Can you pay me back today?", "Ты можешь вернуть мне деньги сегодня?"], ["This shirt is on sale, but it's too tight.", "Эта рубашка на распродаже, но она слишком тесная."], ["I need a fitting room.", "Мне нужна примерочная."], ["Do you have another size?", "У вас есть другой размер?"], ["Hey, what do you think of this dress?", "Привет, как тебе это платье?"]]}, {"unit": 106, "cefr": "A2", "title": "Решай проблемы видеозвонка", "phrases": [["Can I chat with you for a minute?", "Можно с тобой на минутку поболтать?"], ["Please mute yourself when others are talking.", "Пожалуйста, отключайте звук у себя, когда другие говорят."], ["I think there's a bad connection.", "Я думаю, связь плохая."], ["Unmute yourself before you speak, please.", "Включите звук, прежде чем говорить, пожалуйста."], ["How do I mute myself?", "Как мне выключить микрофон?"]]}, {"unit": 107, "cefr": "A2", "title": "Обсуди любимые сериалы", "phrases": [["This show is fantastic!", "Это шоу фантастическое!"], ["In my opinion, it was a little boring.", "По-моему, это было немного скучно."], ["How about we try this show?", "Как насчёт посмотреть это шоу?"], ["Do you ever watch reality TV?", "Ты когда-нибудь смотришь реалити-шоу?"], ["The latest season was excellent!", "Последний сезон был отличным!"]]}, {"unit": 108, "cefr": "A2", "title": "Посети культурные места уважительно", "phrases": [["Let's go sightseeing!", "Пойдём смотреть достопримечательности!"], ["I bought a souvenir.", "Я купил сувенир."], ["We saw the ballet at the theater.", "Мы посмотрели балет в театре."], ["Are you excited to try something new?", "Ты горишь желанием попробовать что‑то новое?"], ["The guide will show us old castles.", "Гид покажет нам старинные замки."]]}, {"unit": 109, "cefr": "A2", "title": "Обсуди успехи с учителем", "phrases": [["I need him to explain this vocabulary.", "Мне нужно, чтобы он объяснил эту лексику."], ["Did you pass your test?", "Ты сдал тест?"], ["Please write the vocabulary on the whiteboard!", "Пожалуйста, запишите слова на белой доске!"], ["I certainly studied all day!", "Я, конечно, занимался весь день!"], ["Let's compare our answers.", "Давайте сравним наши ответы."]]}, {"unit": 110, "cefr": "A2", "title": "Обсуди исторические политические события", "phrases": [["Life has changed in the last century.", "Жизнь изменилась за последний век."], ["The war was between two countries.", "Война была между двумя странами."], ["They moved because of the war.", "Они переехали из-за войны."], ["Most people lived on farms in the past.", "Большинство людей жили на фермах в прошлом."], ["There was a war two centuries ago.", "Была война два века назад."]]}, {"unit": 111, "cefr": "A2", "title": "Опиши годовщину свадьбы", "phrases": [["It's our 3rd anniversary.", "Это наша третья годовщина."], ["We were taking photos of the sunset at six.", "Мы фотографировали закат в шесть."], ["Everyone came to the party, including Kevin.", "Все пришли на вечеринку, включая Кевина."], ["They got married on September 23rd.", "Они поженились двадцать третьего сентября."], ["We were dancing under the stars all night.", "Мы танцевали под звёздами всю ночь."]]}, {"unit": 112, "cefr": "A2", "title": "Отвечай на вопросы в экстренных случаях", "phrases": [["I broke my foot while I was skiing.", "Я сломал стопу, пока я катался на лыжах."], ["Do you have any heart problems?", "У вас есть проблемы с сердцем?"], ["I was dizzy, so I sat down.", "У меня закружилась голова, поэтому я сел."], ["The doctor checked my heart.", "Врач послушал моё сердце."], ["I need to see a heart doctor.", "Мне нужно к кардиологу."]]}, {"unit": 113, "cefr": "A2", "title": "Обсуди книги в книжном магазине", "phrases": [["This bookstore feels cozy!", "В этом книжном магазине уютно!"], ["Do your kids like books about pigs?", "Твои дети любят книги про свиней?"], ["Honestly, that series doesn't look good.", "Честно, тот сериал выглядит не очень."], ["What about these books instead?", "А как насчёт этих книг?"], ["I love mystery novels.", "Я люблю детективные романы."]]}, {"unit": 114, "cefr": "A2", "title": "Спланируй поход с палатками", "phrases": [["We're camping by a river.", "Мы разбили лагерь у реки."], ["Let's roast potatoes tonight.", "Давай запечём картошку сегодня вечером."], ["Bring a pair of sandals.", "Принеси пару сандалий."], ["Are there bears in the woods?", "В лесу есть медведи?"], ["I'll make a campfire when we arrive.", "Я разведу костёр, когда мы приедем."]]}, {"unit": 115, "cefr": "A2", "title": "Опиши поход в музей", "phrases": [["Emma says that this gallery is really pretty!", "Эмма говорит, что эта галерея очень красивая!"], ["The sculpture was made of glass.", "Скульптура была сделана из стекла."], ["Who painted the dragon?", "Кто нарисовал дракона?"], ["I loved everything except the weather.", "Мне очень понравилось всё, кроме погоды."], ["The guide said that the artist was Canadian.", "Гид сказал, что художник был канадцем."]]}, {"unit": 116, "cefr": "A2", "title": "Утешь семью", "phrases": [["Are you OK, Grandma?", "Ты в порядке, бабушка?"], ["Don't worry, I'll look after you!", "Не волнуйся, я присмотрю за тобой!"], ["You will be healthy again soon!", "Вы скоро снова будете здоровы!"], ["I'm sorry your back hurts!", "Мне жаль, что у тебя болит спина!"], ["The doctor says you'll breathe better soon.", "Доктор говорит, что вы скоро будете дышать лучше."]]}, {"unit": 117, "cefr": "A2", "title": "Подтверди детали футбольного турнира", "phrases": [["Do you want to sign up for the tournament?", "Ты хочешь записаться на турнир?"], ["The best team will win a prize!", "Лучшая команда выиграет приз!"], ["I want to play against the best players!", "Я хочу играть против лучших игроков!"], ["Do you mind if I join the team?", "Вы не возражаете, если я присоединюсь к команде?"], ["We need more practice before the first game.", "Нам нужно больше тренировок перед первой игрой."]]}, {"unit": 118, "cefr": "A2", "title": "Обсуди чувства и решения", "phrases": [["We can talk about our feelings.", "Мы можем говорить о своих чувствах."], ["He wasn't embarrassed.", "Он не был смущён."], ["Why were you embarrassed?", "Почему тебе было неловко?"], ["Yesterday was the end of our relationship!", "Вчера пришёл конец нашим отношениям!"], ["Anyway, we're friends again.", "В любом случае, мы снова друзья."]]}, {"unit": 119, "cefr": "A2", "title": "Организовывай пикник в парке", "phrases": [["I'm off on Monday, so let's have a picnic!", "У меня в понедельник выходной, так что давай устроим пикник!"], ["Can you open this jar of peanut butter?", "Можешь открыть эту банку арахисового масла?"], ["Tomorrow's good for me.", "Завтра мне удобно."], ["I just invited Kevin to the picnic.", "Я только что пригласил Кевина на пикник."], ["First of all, let's find a good spot.", "Прежде всего, давай найдём хорошее место."]]}, {"unit": 120, "cefr": "A2", "title": "Обсуди планы на фитнес в выходные", "phrases": [["I like long walks in the mountains.", "Мне нравятся долгие прогулки в горах."], ["We lift weights in pairs.", "Мы поднимаем тяжести парами."], ["Did you take a walk?", "Вы прогулялись?"], ["Keeping fit is important in our family.", "В нашей семье важно поддерживать форму."], ["I was going to exercise, but I had to leave.", "Я собирался потренироваться, но мне пришлось уйти."]]}, {"unit": 121, "cefr": "A2", "title": "Выбери университетские курсы", "phrases": [["Do you trust your professor?", "Ты доверяешь своему профессору?"], ["I need to look at the university website.", "Мне нужно посмотреть сайт университета."], ["Neither of the questions is on the test.", "В тесте нет ни одного из вопросов."], ["Either diploma is useful!", "Любой из двух дипломов полезен!"], ["Can I change my schedule?", "Могу ли я изменить своё расписание?"]]}, {"unit": 122, "cefr": "A2", "title": "Опиши недавнее преступление", "phrases": [["Maybe the robber left this cigarette here.", "Может быть, грабитель оставил эту сигарету здесь."], ["The police officers weren't delayed.", "Полицейские не задержались."], ["Excuse me, could you repeat that?", "Извините, могли бы вы повторить это?"], ["The security cameras were covered.", "Камеры видеонаблюдения были прикрыты."], ["Why did the robber leave a hat here?", "Почему грабитель оставил шляпу здесь?"]]}, {"unit": 123, "cefr": "A2", "title": "Узнавай о достопримечательностях", "phrases": [["Walk north for three blocks.", "Идите на север три квартала."], ["Where can we exchange money?", "Где можно обменять деньги?"], ["People often pray at this spot.", "Люди часто молятся на этом месте."], ["This square is famous.", "Эта площадь знаменита."], ["Let's go and see the sculptures.", "Пойдём посмотрим на скульптуры."]]}, {"unit": 124, "cefr": "A2", "title": "Помоги детям с домашней работой", "phrases": [["It's important to do your homework.", "Важно делать своё домашнее задание."], ["Can you guess the answer?", "Можешь угадать ответ?"], ["The first question is often the easiest.", "Первый вопрос часто бывает самым лёгким."], ["Draw a straight line under your name.", "Проведи прямую линию под своим именем."], ["The assignments are difficult but short.", "Задания сложные, но короткие."]]}, {"unit": 125, "cefr": "A2", "title": "Объясни рецепт блюда", "phrases": [["Do you know how to make bagels?", "Ты знаешь, как печь бублики?"], ["Should I use red or yellow peppers?", "Стоит ли мне использовать красный или жёлтый перец?"], ["Mix the ingredients for thirty seconds.", "Перемешивайте ингредиенты в течение тридцати секунд."], ["We should only use real ingredients.", "Нам следует использовать только натуральные ингредиенты."], ["How many eggs do we use for one omelet?", "Сколько яиц мы берём на один омлет?"]]}, {"unit": 126, "cefr": "A2", "title": "Обсуди учебное приложение", "phrases": [["I can get into that school, can't I?", "Я смогу поступить в ту школу, да?"], ["Which colleges are you applying to?", "В какие колледжи ты подаёшь документы?"], ["I'm just starting the application.", "Я только начинаю заполнять заявление."], ["I don't know if my grades are good enough.", "Я не знаю, достаточно ли хороши мои оценки."], ["You'll apply to medical school, won't you?", "Ты подашь документы в медицинский университет, правда?"]]}, {"unit": 127, "cefr": "A2", "title": "Организуй барбекю вечеринку", "phrases": [["Let's have a barbecue!", "Давайте устроим барбекю!"], ["The meat that you cooked looks yummy.", "Мясо, которое ты приготовил, выглядит вкусно."], ["Could you pass the cheeseburgers, please?", "Могли бы вы передать чизбургеры, пожалуйста?"], ["I really like barbecues!", "Мне очень нравится барбекю!"], ["You're an amazing cook!", "Ты потрясающий повар!"]]}, {"unit": 128, "cefr": "A2", "title": "Наблюдай за людьми на мероприятиях", "phrases": [["Look, an electric truck!", "Смотри, электрический грузовик!"], ["The woman who talked to you is named Amy.", "Женщину, которая с тобой разговаривала, зовут Эми."], ["I've never seen an opera.", "Я никогда не видел ни одной оперы."], ["The man who drives the bus looks sleepy.", "Мужчина, который управляет автобусом, выглядит сонным."], ["The opera singer also works as a clown!", "Оперный певец тоже работает клоуном!"]]}, {"unit": 129, "cefr": "A2", "title": "Открой счёт в банке", "phrases": [["Where is the closest ATM?", "Где ближайший банкомат?"], ["I'd like to open a bank account here.", "Я хотел бы открыть здесь банковский счёт."], ["Can I pay by check?", "Можно заплатить чеком?"], ["Is there a place where I can find an ATM?", "Где я могу найти банкомат?"], ["How long does it take to open an account?", "Сколько времени нужно, чтобы открыть счёт?"]]}, {"unit": 130, "cefr": "B1", "title": "Расскажи о своей поездке / Добраться до отеля / Пожить в отеле / Опиши свою поездку", "phrases": [["I thought I reserved a no-smoking room!", "Я думал, что я забронировал номер для некурящих!"], ["Traveling solo is cool, but I'm a little homesick.", "Путешествовать одному классно, но я немного тоскую по дому."], ["Can I use public transportation to get to that museum?", "Могу ли я воспользоваться общественным транспортом, чтобы добраться до этого музея?"], ["I'm flying to Europe for the first time!", "Я лечу в Европу в первый раз!"], ["A shuttle can take you downtown.", "Трансфер может отвезти вас в центр города."]]}, {"unit": 135, "cefr": "B1", "title": "Обсуди варианты ужина / Расскажи о еде и аллергиях / Выбери вкусное блюдо / Опиши вкус напитков / Закажи и оплати еду", "phrases": [["If we order delivery, when will the food arrive?", "Если мы закажем доставку, когда прибудет еда?"], ["I don't want to cook, so let's order delivery.", "Я не хочу готовить, так что давай закажем доставку."], ["This app is the fastest way to order pizza.", "Это приложение – самый быстрый способ заказать пиццу."], ["How much was the total for everything we ordered?", "Сколько была общая сумма за всё, что мы заказали?"], ["I always check the ingredients because I can't eat eggs.", "Я всегда проверяю ингредиенты, потому что мне нельзя есть яйца."]]}, {"unit": 140, "cefr": "B1", "title": "Обсуди учёбу и экзамены / Готовься к экзамену / Обсуди задания / Поговори о школе / Обсуди планы по учёбе", "phrases": [["Class starts in five minutes, so hurry up!", "Занятие начинается через пять минут, так что поторопись!"], ["Did you understand the professor's lecture?", "Ты поняла лекцию профессора?"], ["I have science next, so I'm going to the laboratory.", "У меня дальше естественные науки, поэтому я иду в лабораторию."], ["You'll get a certificate at the end of the course.", "Вы получите сертификат в конце курса."], ["Translate all the sentences into English.", "Переведите все предложения на английский."]]}, {"unit": 145, "cefr": "B1", "title": "Расскажи о поиске работы / Рассказать о себе / Расскажи о своей работе / Поговори о новой работе", "phrases": [["I would like to apply for a job there.", "Я бы хотел подать заявку на работу там."], ["Have you done a similar job before?", "Делали ли вы похожую работу раньше?"], ["I quit my job last month, so I'm not working now.", "Я уволился с работы в прошлом месяце, поэтому сейчас не работаю."], ["What kind of benefits do workers receive?", "Какие виды льгот получают работники?"], ["I have a job interview at two o'clock.", "У меня собеседование на работу в два часа."]]}, {"unit": 150, "cefr": "B1", "title": "Опиши беспорядок в доме / Поговори об уборке дома / Обсуди дела по дому / Расскажи о домашних делах", "phrases": [["Can you help me clean up in the kitchen?", "Ты можешь мне помочь прибраться в кухне?"], ["I don't mind cooking, but I really dislike cleaning!", "Я не против готовки, но мне очень не нравится прибираться!"], ["We have to clean the house before our guests arrive!", "Нам нужно прибраться в доме до того, как прибудут наши гости!"], ["My roommate and I share the housework.", "Мы с соседкой по квартире делим работу по дому."], ["Please vacuum the floor when you clean your room.", "Пожалуйста, пропылесось пол, когда будешь прибираться в своей комнате."]]}, {"unit": 155, "cefr": "B1", "title": "Проверь всё перед звонком / Поболтай на созвоне / Поговори о погоде / Обсудим погоду и работу / Обсудить повестку встречи", "phrases": [["First, let's discuss the new project.", "Сначала давайте обсудим новый проект."], ["It's rainy and cloudy outside right now.", "Сейчас на улице дождливо и облачно."], ["Hopefully, Emma will be here on time.", "Я надеюсь, Эмма будет здесь вовремя."], ["Did everyone get the agenda for today's meeting?", "Все получили повестку сегодняшнего собрания?"], ["Isn't it beautiful when the leaves change colors?", "Разве не прекрасно, когда листья меняют цвета?"]]}, {"unit": 160, "cefr": "B1", "title": "Поддерживай связь / Встреть старых друзей / Вспомни школьных друзей / Общаться на вечеринке / Попрощайся с друзьями", "phrases": [["Our class gets together every summer.", "Наш класс собирается вместе каждое лето."], ["Hello, Ben, what's up?", "Привет, Бен, как дела?"], ["I'd like you to meet an old classmate of mine.", "Я бы хотела познакомить тебя со своим бывшим одноклассником."], ["We haven't gotten together for five years!", "Мы не собирались вместе пять лет!"], ["Cheers to the best class of Sun City High School!", "Выпьем за лучший класс старшей школы Сан Сити!"]]}, {"unit": 165, "cefr": "B1", "title": "Опиши своё состояние / Опиши свои симптомы / Опиши болезни и травмы / Купить лекарства в аптеке", "phrases": [["Stay home if you have a fever.", "Оставайся дома, если у тебя температура."], ["I need a bandage because my finger is bleeding.", "Мне нужен бинт, потому что у меня палец в крови."], ["My head didn't hurt yesterday, but today it does.", "Вчера у меня не болела голова, но сегодня болит."], ["The doctor told me to take some aspirin.", "Врач сказал мне принять аспирин."], ["If it hurts badly, call a doctor.", "Если будет сильно болеть, вызови врача."]]}, {"unit": 170, "cefr": "B1", "title": "Расскажи о жизни в сети / Расскажи о блоге друга / Назови плюсы соцсетей / Общайся в интернете / Расскажи про технологии", "phrases": [["Technology has changed the way we communicate.", "Технологии изменили наш способ общения."], ["Don't share any private information online.", "Не делись никакой личной информацией онлайн."], ["Have you ever read Maria's food blog?", "Вы когда-нибудь читали кулинарный блог Марии?"], ["I use the app to communicate with friends.", "Я использую приложение, чтобы общаться с друзьями."], ["Click on the link to the video.", "Нажми на ссылку к этому видео."]]}, {"unit": 175, "cefr": "B1", "title": "Опиши утренние привычки / Расскажи о своём утре / Опиши своё утро / Опиши события и чувства / Расслабься в конце дня", "phrases": [["She hugs her doll when she's scared.", "Она обнимает свою куклу, когда ей страшно."], ["My husband shaves every morning before breakfast.", "Мой муж бреется каждое утро перед завтраком."], ["The kids need lots of time to play after school.", "Детям нужно много времени на игры после школы."], ["I watch a TV series while I eat breakfast.", "Я смотрю телесериал, пока ем завтрак."], ["Taking a bath will help you relax.", "Принятие ванны поможет тебе расслабиться."]]}, {"unit": 180, "cefr": "B1", "title": "Расскажи сказку на ночь / Опиши волшебный мир / Расскажи об опасностях / Опиши главные события / Опиши праздник во дворце", "phrases": [["She was surprised to discover that her cow could talk!", "Она удивилась, обнаружив, что её корова умеет говорить!"], ["The princess waved at the prince and said goodbye.", "Принцесса помахала принцу и попрощалась."], ["Look out, there's a bear behind you!", "Берегись, позади тебя медведь!"], ["The king got angry because nobody came to his party.", "Король разозлился, потому что никто не пришёл на его вечеринку."], ["The fireworks in the sky were amazing!", "Фейерверк в небе был потрясающим!"]]}, {"unit": 185, "cefr": "B1", "title": "Расскажи о свадьбе друга / Опиши хаос на свадьбе / Рассказать о свадьбе / Описать свадьбу / Опиши свадебную церемонию", "phrases": [["Today is Ben and Lisa's wedding!", "Сегодня свадьба Бена и Лизы!"], ["The bride and groom usually exchange rings.", "Невеста и жених обычно обмениваются кольцами."], ["The ceremony lasted about two hours.", "Церемония длилась около двух часов."], ["The groom smiled when he saw his bride.", "Жених улыбнулся, когда увидел свою невесту."], ["Let's celebrate Max and Maria's wedding!", "Давайте отпразднуем свадьбу Макса и Марии!"]]}, {"unit": 190, "cefr": "B1", "title": "Опиши своё детство / Расскажи о детстве / Расскажи о переменах / Расскажи о прошлом", "phrases": [["My mom used to make the best pies.", "Моя мама раньше пекла лучшие пироги."], ["I used to love making pies with my mom.", "Раньше я любил печь пироги с мамой."], ["My family used to live in a quiet neighborhood.", "Моя семья раньше жила в тихом районе."], ["I never used to eat fish, but now I do.", "Я никогда раньше не ел рыбу, но теперь ем."], ["We often played cards after school.", "Мы часто играли в карты после школы."]]}, {"unit": 195, "cefr": "B1", "title": "Расскажи о соседях / Поговорите о гостях / Расскажи о своих близких / Поговорим о супругах / Обсуждать свои отношения", "phrases": [["My niece and nephew both have curly hair!", "Моя племянница и племянник оба кудрявые!"], ["David's spouse is a famous and successful chef!", "Супруг Дэвида это известный и успешный шеф-повар!"], ["Max and Lisa are in a happy marriage.", "Макс и Лиза в счастливом браке."], ["My dream is to retire early!", "Я мечтаю рано уйти на пенсию!"], ["Do you know where they first met?", "Вы знаете, где они впервые встретились?"]]}, {"unit": 200, "cefr": "B1", "title": "Обосновать выбор одежды / Оценить качество одежды / Купить одежду в магазине / Купим одежду и пообедаем / Купить одежду со скидкой", "phrases": [["I need to buy a new sweatshirt.", "Мне нужно купить новую толстовку."], ["Doesn't this coat look too big on me?", "Это пальто на мне не слишком большое?"], ["Anna tried on different hats and took selfies.", "Анна примеряла разные шляпы и делала селфи."], ["Could you put the change in my wallet?", "Не могли бы вы положить сдачу в мой кошелёк?"], ["Let's buy these shoes and get some lunch afterward.", "Давай купим эти туфли и потом пообедаем."]]}, {"unit": 205, "cefr": "B1", "title": "Уточни детали перелёта / Попроси помощи в аэропорту / Расскажи о своём приезде / Говорить о поездках / Готовиться к перелёту", "phrases": [["Shouldn't we look for a cheaper ticket?", "Не поищем ли билет подешевле?"], ["I told her where to meet us.", "Я сказал ей, где встретиться с нами."], ["Can't I order a vegetarian meal instead?", "Нельзя ли мне вместо этого заказать вегетарианское блюдо?"], ["The line for airport security is long.", "Очередь на контроль безопасности в аэропорту длинная."], ["You can find cheap tickets online.", "Ты можешь найти дешёвые билеты в интернете."]]}, {"unit": 210, "cefr": "B1", "title": "Обсуди последние новости", "phrases": [["It's common to read the news on social media.", "Читать новости в социальных сетях — обычное дело."], ["The lawyer stood next to the man in court.", "Адвокат стоял рядом с мужчиной в суде."], ["Did you see today's headlines?", "Вы видели сегодняшние заголовки?"], ["The highway was closed because of a car crash.", "Шоссе было перекрыто из-за аварии."], ["The spy stole information from the government.", "Шпион украл информацию у правительства."]]}];
